import type {
  DataDrivenPropertyValueSpecification,
  ExpressionSpecification,
  LayerSpecification,
  StyleSpecification,
} from 'maplibre-gl';

/**
 * Dark, CarPlay-like MapLibre style for ATS/ETS2 tiles generated by
 * truckermudgeon/maps (scripts/maps/build.sh). Layer filters and the feature
 * schema follow upstream's GameMapStyle.tsx / BaseMapStyle.tsx; colours are ours.
 */

export type Game = 'ats' | 'ets2';

export const C = {
  land: '#1e1f22',
  water: '#1b2a3d',
  stateBorder: '#4a4b50',
  countryBorder: '#5a5b60',
  footprint: '#2a2b2f',
  hiddenRoad: '#2f3034',
  ferry: '#4f6fae',
  text: 'hsl(220, 8%, 86%)',
  textDim: 'hsl(220, 6%, 64%)',
  halo: '#141517',
  route: '#0a84ff',
  routeCase: '#0b4a94',
};

// [fill, casing] per roadType
export const ROAD: Record<string, [string, string]> = {
  freeway: ['#8a7646', '#3b3324'],
  divided: ['#5b5c62', '#34353a'],
  local: ['#4a4b50', '#2d2e32'],
  no_vehicles: ['#38393d', '#2a2b2f'],
  train: ['#555', '#333'],
  tram: ['#555', '#333'],
  unknown: ['#4a4b50', '#2d2e32'],
};

// MapAreaColor enum (road, light, dark, green, nav-*) -> fill
export const AREA = [
  'hsl(220, 3%, 30%)',
  'hsl(38, 12%, 26%)',
  'hsl(38, 12%, 21%)',
  'hsl(143, 14%, 20%)',
  'hsl(0, 60%, 24%)',
  'hsl(107, 35%, 22%)',
  'hsl(201, 40%, 24%)',
  'hsl(53, 50%, 24%)',
  'hsl(267, 30%, 24%)',
];

const match = (prop: string, table: Record<string, string> | string[], fallback: string): ExpressionSpecification =>
  [
    'match',
    ['get', prop],
    ...Object.entries(table).flatMap(([k, v]) => [Array.isArray(table) ? Number(k) : k, v]),
    fallback,
  ] as unknown as ExpressionSpecification;

const roadFill = match('roadType', Object.fromEntries(Object.entries(ROAD).map(([k, v]) => [k, v[0]])), '#4a4b50');
const roadCase = match('roadType', Object.fromEntries(Object.entries(ROAD).map(([k, v]) => [k, v[1]])), '#2d2e32');
const areaFill = match('color', AREA, AREA[0]);

const roadWidth: DataDrivenPropertyValueSpecification<number> = [
  'interpolate', ['exponential', 1.5], ['zoom'],
  3, 0.8,
  14, 30,
  16, 150,
];
/** roadWidth evaluated in JS (for the 2D fallback): MapLibre's exponential interpolation, base 1.5. */
export function roadWidthPx(zoom: number): number {
  const stops: [number, number][] = [[3, 0.8], [14, 30], [16, 150]];
  if (zoom <= stops[0][0]) return stops[0][1];
  for (let i = 1; i < stops.length; i++) {
    const [z0, w0] = stops[i - 1];
    const [z1, w1] = stops[i];
    if (zoom <= z1) return w0 + ((1.5 ** (zoom - z0) - 1) / (1.5 ** (z1 - z0) - 1)) * (w1 - w0);
  }
  return stops[stops.length - 1][1];
}

const caseWidth: DataDrivenPropertyValueSpecification<number> = [
  'interpolate', ['exponential', 1.5], ['zoom'],
  10, 1,
  14, 2,
  16, 3,
];

const font = ['Klokantech Noto Sans Regular'];
const textPaint = { 'text-color': C.text, 'text-halo-color': C.halo, 'text-halo-width': 1.5 };

function iconSize(z4: number, z9: number, z13: number): DataDrivenPropertyValueSpecification<number> {
  return ['interpolate', ['exponential', 1.5], ['zoom'], 4, z4, 9, z9, 13, z13];
}

const isLine: ExpressionSpecification = ['==', ['geometry-type'], 'LineString'];
const isPoint: ExpressionSpecification = ['==', ['geometry-type'], 'Point'];
const isPolygon: ExpressionSpecification = ['==', ['geometry-type'], 'Polygon'];
const typeIs = (t: string): ExpressionSpecification => ['==', ['get', 'type'], t];
const visibleRoad: ExpressionSpecification = [
  'all', isLine, typeIs('road'), ['!=', ['get', 'roadType'], 'train'], ['==', ['get', 'hidden'], false],
];

/** Facility icons worth showing while driving (fuel, rest, service…). */
const POI_SPRITES = ['gas_ico', 'service_ico', 'parking_ico', 'weigh_station_ico', 'garage_large_ico', 'dealer_ico', 'recruitment_ico'];
const ROAD_FACILITY_SPRITES = ['weigh_ico', 'toll_ico', 'agri_check', 'border_ico'];

function gameLayers(game: Game): LayerSpecification[] {
  const src = { source: game, 'source-layer': game };
  const layers: LayerSpecification[] = [
    {
      id: 'map-areas', type: 'fill', ...src,
      filter: ['all', isPolygon, typeIs('mapArea')],
      layout: { 'fill-sort-key': ['get', 'zIndex'] },
      paint: { 'fill-color': areaFill },
    },
    {
      id: 'prefabs', type: 'fill', ...src,
      filter: ['all', isPolygon, typeIs('prefab')],
      layout: { 'fill-sort-key': ['get', 'zIndex'] },
      paint: { 'fill-color': areaFill },
    },
    {
      id: 'footprints', type: 'fill', source: 'footprints', 'source-layer': 'footprints',
      filter: ['all', isPolygon, typeIs('footprint')],
      paint: { 'fill-color': C.footprint },
    },
    {
      id: 'hidden-roads', type: 'line', ...src, minzoom: 9,
      filter: ['all', isLine, typeIs('road'), ['==', ['get', 'hidden'], true]],
      paint: { 'line-color': C.hiddenRoad, 'line-width': 1 },
    },
    {
      id: 'roads-case', type: 'line', ...src, filter: visibleRoad,
      layout: { 'line-cap': 'round', 'line-join': 'bevel' },
      paint: { 'line-color': roadCase, 'line-gap-width': roadWidth, 'line-width': caseWidth },
    },
    {
      id: 'roads', type: 'line', ...src, filter: visibleRoad,
      layout: { 'line-cap': 'round', 'line-join': 'bevel' },
      paint: { 'line-color': roadFill, 'line-width': roadWidth },
    },
    {
      id: 'ferries', type: 'line', ...src,
      filter: ['all', isLine, typeIs('ferry')],
      paint: { 'line-color': C.ferry, 'line-width': 1, 'line-dasharray': [2, 2] },
    },
    // Route goes above roads, below labels.
    {
      id: 'route-case', type: 'line', source: 'route',
      layout: { 'line-cap': 'round', 'line-join': 'round' },
      paint: { 'line-color': C.routeCase, 'line-width': ['interpolate', ['linear'], ['zoom'], 6, 5, 10, 9, 14, 16] },
    },
    {
      id: 'route', type: 'line', source: 'route',
      layout: { 'line-cap': 'round', 'line-join': 'round' },
      paint: { 'line-color': C.route, 'line-width': ['interpolate', ['linear'], ['zoom'], 6, 3, 10, 6, 14, 11] },
    },
    {
      id: 'exits', type: 'symbol', ...src, minzoom: 10,
      filter: ['all', isPoint, typeIs('exit')],
      layout: {
        'text-field': '{name}', 'text-font': font,
        'text-size': ['interpolate', ['linear'], ['zoom'], 4, 4, 10, 10],
        'icon-image': 'exit-sign', 'icon-text-fit': 'both', 'icon-text-fit-padding': [0, 2, 0, 2],
        'icon-size': iconSize(0.4, 0.75, 1.25),
      },
      paint: { 'text-color': '#fff' },
    },
    {
      id: 'road-shields', type: 'symbol', ...src, minzoom: 5,
      filter: [
        'all', isPoint, typeIs('poi'), ['==', ['get', 'poiType'], 'road'],
        ['!', ['in', ['get', 'sprite'], ['literal', ROAD_FACILITY_SPRITES]]],
      ],
      layout: {
        'icon-image': '{sprite}',
        'icon-size': game === 'ats' ? iconSize(0.4, 0.75, 1.25) : iconSize(0.5, 0.94, 1.56),
        'icon-padding': ['literal', [10, 30]],
      },
    },
    {
      id: 'pois', type: 'symbol', ...src, minzoom: 9,
      filter: [
        'all', isPoint, typeIs('poi'),
        [
          'any',
          ['all', ['==', ['get', 'poiType'], 'facility'], ['in', ['get', 'sprite'], ['literal', POI_SPRITES]]],
          ['all', ['==', ['get', 'poiType'], 'road'], ['in', ['get', 'sprite'], ['literal', ROAD_FACILITY_SPRITES]]],
        ],
      ],
      layout: { 'icon-image': '{sprite}', 'icon-size': iconSize(0.6, 1.0, 1.8), 'icon-padding': ['literal', [2, 2]] },
    },
    {
      id: 'companies', type: 'symbol', ...src, minzoom: 10,
      filter: ['all', isPoint, typeIs('poi'), ['==', ['get', 'poiType'], 'company']],
      layout: { 'icon-image': '{sprite}', 'icon-size': iconSize(1, 1.25, 3) },
    },
  ];
  // City labels by size; small towns only when zoomed in.
  const cities: [string, ExpressionSpecification, number, number, number][] = [
    ['cities-big', ['<=', ['get', 'scaleRank'], 3], 4, 11, 15],
    ['cities-medium', ['all', ['<=', ['get', 'scaleRank'], 6], ['>', ['get', 'scaleRank'], 3]], 5, 11.5, 14],
    ['cities-small', ['>', ['get', 'scaleRank'], 6], 6, 12, 13],
  ];
  for (const [id, rank, minzoom, maxzoom, size] of cities) {
    layers.push({
      id, type: 'symbol', ...src, minzoom, maxzoom,
      filter: ['all', isPoint, typeIs('city'), rank],
      layout: { 'text-field': '{name}', 'text-font': font, 'text-size': size, 'text-padding': 8 },
      paint: textPaint,
    });
  }
  return layers;
}

export function mapStyle(game: Game, base: string): StyleSpecification {
  return {
    version: 8,
    // Free font glyphs (needs internet; same as upstream).
    glyphs: 'https://fonts.openmaptiles.org/{fontstack}/{range}.pbf',
    sprite: `${base}/sprites`,
    sources: {
      world: { type: 'vector', url: `pmtiles://${base}/world.pmtiles` },
      [game]: { type: 'vector', url: `pmtiles://${base}/${game}.pmtiles` },
      footprints: { type: 'vector', url: `pmtiles://${base}/${game}-footprints.pmtiles` },
      route: { type: 'geojson', data: { type: 'FeatureCollection', features: [] } },
    },
    layers: [
      { id: 'background', type: 'background', paint: { 'background-color': C.land } },
      { id: 'water', type: 'fill', source: 'world', 'source-layer': 'water', paint: { 'fill-color': C.water } },
      {
        id: 'states', type: 'line', source: 'world', 'source-layer': 'states',
        paint: { 'line-color': C.stateBorder, 'line-width': 1, 'line-dasharray': [2, 2] },
      },
      {
        id: 'countries', type: 'line', source: 'world', 'source-layer': 'countries',
        paint: { 'line-color': C.countryBorder, 'line-width': 1.5 },
      },
      ...gameLayers(game),
    ],
  };
}

/** Green exit-number sign, stretched around the text (generated, as upstream does). */
export function exitSignImage() {
  const size = 64;
  const data = new Uint8Array(size * size * 4);
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const o = (y * size + x) * 4;
      const edge = Math.min(x, y, size - 1 - x, size - 1 - y);
      const [r, g, b] = edge === 0 ? [0x88, 0x88, 0x88] : edge <= 2 ? [0xff, 0xff, 0xff] : [0x1f, 0x7a, 0x4d];
      data.set([r, g, b, 255], o);
    }
  }
  const pad = 8;
  return {
    image: { width: size, height: size, data },
    options: {
      stretchX: [[pad, size - pad]] as [number, number][],
      stretchY: [[pad, size - pad]] as [number, number][],
      content: [pad, pad, size - pad, size - pad] as [number, number, number, number],
      pixelRatio: 2,
    },
  };
}
